import React from 'react';

const Motor3D = () => {
  return (
    <div className="motor-3d-container">
      <div className="motor-3d">
        {/* Motor Stator (Main Body) */}
        <div className="motor-stator">
          <div className="stator-face front"></div>
          <div className="stator-face back"></div>
          <div className="stator-face left"></div>
          <div className="stator-face right"></div>
          <div className="stator-face top"></div>
          <div className="stator-face bottom"></div>
        </div>

        {/* End Bells */}
        <div className="end-bell front-bell"></div>
        <div className="end-bell back-bell"></div>

        {/* Motor Shaft */}
        <div className="motor-shaft">
          <div className="shaft-extension"></div>
          <div className="shaft-keyway"></div>
        </div>

        {/* Cooling Fan */}
        <div className="cooling-fan">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="fan-blade" style={{transform: `rotateZ(${i * 60}deg)`}}></div>
          ))}
          <div className="fan-center"></div>
        </div>

        {/* Cooling Fins */}
        <div className="cooling-fins">
          {[...Array(12)].map((_, i) => (
            <div key={i} className="fin" style={{transform: `rotateY(${i * 30}deg)`}}></div>
          ))}
        </div>

        {/* Terminal Box */}
        <div className="terminal-box">
          <div className="terminal-cover"></div>
          <div className="terminal-screw"></div>
          <div className="terminal-screw terminal-screw-2"></div>
        </div>

        {/* Motor Feet */}
        <div className="motor-foot foot-1"></div>
        <div className="motor-foot foot-2"></div>
        <div className="motor-foot foot-3"></div>
        <div className="motor-foot foot-4"></div>

        {/* Nameplate */}
        <div className="nameplate">
          <div className="nameplate-text">AMOL ELECTRICALS</div>
          <div className="nameplate-specs">3HP • 1440 RPM • 415V</div>
        </div>

        {/* Conduit Box */}
        <div className="conduit-box"></div>

        {/* Bearing Caps */}
        <div className="bearing-cap front-cap"></div>
        <div className="bearing-cap back-cap"></div>
      </div>
    </div>
  );
};

export default Motor3D;
